}

void sample_consume(int32_t v)
{
    printf("[t=%u] got %d\n", (unsigned)xTaskGetTickCount(), (int)v);
    if (v != g_next_got)
        printf("ERROR: expected sample %d\n", (int)g_next_got);
    g_next_got = v + 1;
    g_gots++;
}

