    g_sent++;
}

void on_dropped(int32_t v)
{
    printf("[t=%u] DROP %d\n", (unsigned)xTaskGetTickCount(), (int)v);
    g_dropped++;
}

void on_logged(int32_t v)
{
    printf("[t=%u] logged %d\n", (unsigned)xTaskGetTickCount(), (int)v);
    g_logged++;
}

/*USER_CODE*/

